#include <bits/stdc++.h>
using namespace std;

bool isUndoubtedlyLucky(int a) {
    int digitsMask = 0;
    while (a > 0) {
        int d = a % 10;
        digitsMask |= (1 << d);
        if (__builtin_popcount(digitsMask) > 2) return false;
        a /= 10;
    }
    return true;
}

